import XCTest

final class NavTests: XCTestCase {
    let outDir = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uiharness"

    func testOpenHelpAndAbout() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
