        if help.waitForExistence(timeout: 5) {
            help.tap()
        } else if helpCell.waitForExistence(timeout: 2) {
            helpCell.tap()
        }
        sleep(2)
        try app.debugDescription.write(toFile: outDir + "/tree2.txt", atomically: true, encoding: .utf8)
